// Block templates (P4 step 2): shadcn's page-level compositions as request trees, generated by `bun run ds:specs` (scripts/ds-snapshot/blocks.mjs)
// into `snapshot/specs/blocks/<style>.json`. A block is not a component kind and has no live link: inserting it writes ordinary design-system layers.

import type { NodeSpec } from '../../model/types';

/** What a request tree holds: text, an icon, a part instance (props, flags and the overrides its `className` carried) or a layout element. */
export type BlockNode =
  | string
  | { icon: string; at?: 'start' | 'end' }
  | { part: string; props?: Record<string, string>; flags?: string[]; attrs?: Record<string, string>; styles?: Record<string, string>; children?: BlockNode[] }
  | { layout: Omit<NodeSpec, 'children'>; children?: BlockNode[] };

/** Per request-node path (child indexes joined by `.`): what the dark scheme changes. `null` removes a key. */
export interface BlockPatch {
  styles?: Record<string, string | null>;
  attrs?: Record<string, string | null>;
  states?: NodeSpec['states'];
  text?: string | null;
  html?: string | null;
}

export interface BlockRecord {
  title: string;
  description?: string;
  /** shadcn's categories (`authentication`, `login`, `sidebar`, `dashboard`). */
  categories: string[];
  /** Natural size of the block's page: the artboard a new insertion creates. */
  size: { width: number; height: number };
  /** Part names the block uses, sorted. */
  components: string[];
  layers: BlockNode[];
  /** The dark scheme as a patch over `layers` (absent: identical), or whole `darkLayers` when the shapes differ. */
  dark?: Record<string, BlockPatch>;
  darkLayers?: BlockNode[];
}

/** A block shadcn ships that this snapshot does not build, with the dependency (or reason) that rules it out. */
export interface SkippedBlock {
  title?: string;
  description?: string;
  categories?: string[];
  dependencies: string[];
  registryDependencies: string[];
  /** Set when the block is skipped for a reason other than its dependencies. */
  reason?: string;
}

export interface BlocksFile {
  v: 1;
  style: string;
  shadcn: string;
  blocksHash: string;
  skipped: Record<string, SkippedBlock>;
  blocks: Record<string, BlockRecord>;
}
